insert into public.secciones (id, nombre, corto, motivo, palabra, descripcion, sinonimos, orden) values ('amor', 'Amor', 'Amor', 'corazon', 'amor', 'Rituales sencillos y progresivos para atraer, endulzar y acercar a esa persona.', array['amor', 'pareja', 'enamorar', 'novio', 'novia', 'esposo', 'esposa', 'relacion', 'ex', 'regrese', 'volver', 'infiel', 'celos']::text[], 0) on conflict (id) do nothing;
insert into public.secciones (id, nombre, corto, motivo, palabra, descripcion, sinonimos, orden) values ('amarres', 'Amarres', 'Amarres', 'amarre', 'una unión firme', 'Los trabajos de unión más intensos del catálogo, para casos difíciles.', array['amarre', 'amarrar', 'atar', 'unir', 'union', 'matrimonio', 'casarse']::text[], 1) on conflict (id) do nothing;
insert into public.secciones (id, nombre, corto, motivo, palabra, descripcion, sinonimos, orden) values ('amorpropio', 'Amor propio y belleza', 'Amor propio', 'rosa', 'reencontrarte contigo', 'Rituales para tu autoestima, tu brillo y tu magnetismo personal.', array['amor propio', 'autoestima', 'belleza', 'bonita', 'atractiva', 'magnetismo', 'glow']::text[], 2) on conflict (id) do nothing;
insert into public.secciones (id, nombre, corto, motivo, palabra, descripcion, sinonimos, orden) values ('abundancia', 'Abundancia y dinero', 'Abundancia', 'monedas', 'abundancia', 'Para que el dinero, los clientes y las oportunidades vuelvan a fluir.', array['dinero', 'abundancia', 'prosperidad', 'negocio', 'clientes', 'ventas', 'trabajo', 'empleo', 'suerte', 'deudas', 'ingresos']::text[], 3) on conflict (id) do nothing;
insert into public.secciones (id, nombre, corto, motivo, palabra, descripcion, sinonimos, orden) values ('limpieza', 'Limpiezas', 'Limpieza', 'escoba', 'limpiar tu energía', 'Para soltar cargas, bloqueos y energías que no te pertenecen.', array['limpieza', 'limpiar', 'despojo', 'mal de ojo', 'envidia', 'brujeria', 'bloqueo', 'cargas', 'energia']::text[], 4) on conflict (id) do nothing;
insert into public.secciones (id, nombre, corto, motivo, palabra, descripcion, sinonimos, orden) values ('proteccion', 'Protección', 'Protección', 'escudo', 'protección', 'Escudos para ti, tu trabajo, tu familia y tus mascotas.', array['proteccion', 'proteger', 'blindaje', 'escudo', 'familia', 'mascota', 'acoso']::text[], 5) on conflict (id) do nothing;
insert into public.secciones (id, nombre, corto, motivo, palabra, descripcion, sinonimos, orden) values ('supremo', 'Amor supremo', 'Supremo', 'velas', 'un trabajo de amor más fuerte', 'Trabajos combinados y potenciados para casos que piden más fuerza.', array['supremo', 'potenciado', 'fuerte', 'combinado']::text[], 6) on conflict (id) do nothing;
insert into public.secciones (id, nombre, corto, motivo, palabra, descripcion, sinonimos, orden) values ('cortes', 'Cortes y separación', 'Cortes', 'tijeras', 'cerrar un ciclo', 'Para romper lazos, soltar y tomar caminos distintos.', array['separar', 'separacion', 'corte', 'soltar', 'olvidar', 'terminar', 'alejar']::text[], 7) on conflict (id) do nothing;
insert into public.secciones (id, nombre, corto, motivo, palabra, descripcion, sinonimos, orden) values ('velas', 'Velas de refuerzo', 'Velas', 'vela', 'reforzar tu trabajo', 'Aceleran, refuerzan y revitalizan cualquier ritual.', array['vela', 'velas', 'velita', 'velon', 'refuerzo', 'acelerar']::text[], 8) on conflict (id) do nothing;
insert into public.secciones (id, nombre, corto, motivo, palabra, descripcion, sinonimos, orden) values ('personalizado', 'Rituales personalizados', 'A medida', 'luna', 'algo hecho a tu medida', 'Para situaciones únicas que no encajan en ningún ritual del catálogo.', array['personalizado', 'a medida', 'especial', 'unico']::text[], 9) on conflict (id) do nothing;
insert into public.secciones (id, nombre, corto, motivo, palabra, descripcion, sinonimos, orden) values ('tarot', 'Tarot', 'Tarot', 'tarot', 'respuestas', 'Todo trabajo de amor empieza con una lectura previa.', array['tarot', 'lectura', 'cartas', 'consulta']::text[], 10) on conflict (id) do nothing;
insert into public.categorias_productos (id, nombre, orden) values ('pociones', 'Pócimas', 0) on conflict (id) do nothing;
insert into public.categorias_productos (id, nombre, orden) values ('pulseras', 'Pulseras', 1) on conflict (id) do nothing;
insert into public.categorias_productos (id, nombre, orden) values ('amuletos', 'Amuletos y cuarzos', 2) on conflict (id) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('endulzamiento', 'servicio', 'amor', 'Endulzamiento', 'Sencillo', 'miel', 50, 180000, null, 'Endulza sus pensamientos, suaviza su carácter y enciende la ternura más profunda de su corazón. Con este ritual lograrás atraer gestos cariñosos, palabras dulces y una conexión emocional irresistible que hará que piense en ti con amor y dulzura cada vez más.', null, array[]::text[], array[]::text[], true, true, 0) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('pegado-a-mi', 'servicio', 'amor', 'Pegado a mí', 'Sencillo', 'amarre', 50, 180000, null, 'Este ritual es perfecto si deseas que esa persona sienta la necesidad de estar a tu lado en todo momento. Ideal para evitar el distanciamiento y asegurarte de que esa persona cree un apego profundo a tu compañía.', null, array[]::text[], array[]::text[], false, true, 1) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('obsesion', 'servicio', 'amor', 'Obsesión', 'Sencillo', 'ojo', 55, 190000, null, 'Intensifica el deseo y los pensamientos de una persona hacia ti. Actúa a nivel mental, haciendo que la persona no pueda sacarte de su pensamiento. Este trabajo es recomendable cuando aún existe comunicación y contacto, ya que esto facilita que los efectos se manifiesten más rápido.', null, array[]::text[], array[]::text[], false, true, 2) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('retorno', 'servicio', 'amor', 'Retorno', 'Sencillo', 'llave', 55, 190000, null, 'Se realiza cuando una persona ha salido de tu vida y tu intención es atraerla de nuevo. Es importante tener en cuenta que este ritual únicamente facilita su regreso, sin alterar sus sentimientos o intenciones hacia ti. Sin embargo, si esta persona siente rabia, rencor o emociones negativas, regresará con estos mismos sentimientos; si deseas que su retorno sea armonioso, lo ideal sería combinarlo con algún otro ritual específico según tu caso.', null, array[]::text[], array[]::text[], true, true, 3) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('vendaje-de-amor', 'servicio', 'amor', 'Vendaje de amor', 'Sencillo', 'candado', 50, 180000, null, 'Este ritual se encarga de que la persona trabajada solo tenga ojos para ti. Es ideal para hombres mujeriegos, ya que ayuda con su fidelidad y exclusividad en una relación. Sin embargo, no cambia los sentimientos existentes de la persona.', null, array[]::text[], array[]::text[], false, true, 4) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('deseo-sexual', 'servicio', 'amor', 'Deseo sexual', 'Sencillo', 'corazon', 50, 180000, null, 'Intensifica la pasión y el magnetismo sexual entre dos personas, haciendo que esa persona te desee intensamente de forma sexual, despertando su lado más profundo y mejorando su libido sexual.', null, array[]::text[], array[]::text[], false, true, 5) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('corderito-manso', 'servicio', 'amor', 'Corderito manso', 'Sencillo', 'hierbas', 50, 180000, null, 'Ayuda a calmar y suavizar el carácter de una persona, haciéndola más dócil, comprensiva y receptiva contigo. Este ritual trabaja a nivel espiritual para calmar impulsos negativos, reducir la agresividad y fomentar una actitud más tranquila y armoniosa. No cambia la esencia de la persona, pero sí ayuda a disminuir conflictos y mejorar la comunicación, siendo ideal para parejas, jefes, familiares o cualquier persona con un temperamento fuerte.', null, array[]::text[], array[]::text[], false, true, 6) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('atraccion', 'servicio', 'amor', 'Atracción', 'Sencillo', 'luna', 50, 180000, null, 'Está diseñado para hacer que la persona que deseas se sienta cada vez más atraída hacia ti, captando su atención de manera natural y progresiva. Potencia tu magnetismo y encanto, volviéndote más irresistible ante sus ojos, sin forzar sentimientos, sino despertando un interés genuino y creciente en ella.', null, array[]::text[], array[]::text[], false, true, 7) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('lluvia-de-detalles', 'servicio', 'amor', 'Lluvia de detalles', 'Sencillo', 'rosa', 60, 200000, null, '¿Quieres que esa persona te mime, te consienta y esté pendiente de cada uno de tus caprichos? Con este ritual despertamos su lado más detallista y complaciente, haciendo que sienta la necesidad de sorprenderte y darte lo mejor. Perfecto para parejas, sugar daddies, padres o cualquier persona de interés. Si notas que ha perdido la emoción de conquistarte o quieres asegurarte de que siempre tenga gestos especiales contigo, este ritual hará que su atención y generosidad giren solo en torno a ti.', null, array[]::text[], array[]::text[], false, true, 8) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('llora-por-mi', 'servicio', 'amor', 'Llora por mí', 'Sencillo', 'ojo', 50, 180000, null, 'Este poderoso ritual trabaja directamente sobre el corazón y la mente de esa persona especial, provocándole un profundo sentimiento de remordimiento cada vez que piense en ti. Sus lágrimas serán el reflejo de todo aquello que no valoró, removiendo su conciencia. Ideal para combinarlo con rituales de retorno o desespero, potenciando aún más su efectividad. ¡Haz que su llanto sea el eco de su necesidad de ti!', null, array[]::text[], array[]::text[], false, true, 9) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('desespero-sencillo', 'servicio', 'amor', 'Desespero sencillo', 'Sencillo', 'vela', 45, 170000, null, 'Es un ritual sencillo pero efectivo, ideal para iniciar el trabajo de desespero en una persona. Ayuda a provocar pensamientos constantes, necesidad de contacto y ganas de buscarte. Funciona como una primera dosis para mover energías cuando la conexión está fría o distante.', null, array[]::text[], array[]::text[], false, true, 10) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('desespero-con-tabaco', 'servicio', 'amor', 'Desespero con tabaco', 'Sencillo', 'vela', 55, 190000, null, 'Este es un ritual más intenso y potente que el de cigarro. El tabaco tiene una fuerza espiritual mayor, ideal para provocar desespero fuerte, ansiedad, necesidad de presencia y pensamientos repetitivos. Perfecto si quieres que esa persona no logre estar en paz hasta que te busque.', null, array[]::text[], array[]::text[], false, true, 11) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('dominado', 'servicio', 'amor', 'Dominado', 'Sencillo', 'candado', 65, 210000, null, 'Ritual para que la persona actúe, decida y se mueva influenciada por tu energía. Ideal cuando deseas tener el control emocional o conductual sobre alguien. Genera obediencia, entrega y deseo de agradarte, sin resistencias. No es para todos los casos, pero cuando se necesita firmeza, es efectivo.', null, array[]::text[], array[]::text[], false, true, 12) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('desespero-fuerte', 'servicio', 'supremo', 'Desespero fuerte', 'Supremo', 'velas', 90, 310000, null, 'Está diseñado para provocar desesperación intensa en la mente, el cuerpo y el espíritu: la persona trabajada sentirá una ansiedad incontrolable que no le permitirá estar en paz hasta que te busque. Al combinarlo con un retorno, los resultados son más efectivos, ya que la necesidad de volver a ti se vuelve irresistible. Este trabajo es agresivo y puede generar síntomas como insomnio, inquietud extrema y angustia constante.', null, array[]::text[], array[]::text[], false, true, 13) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('mayor-compromiso', 'servicio', 'supremo', 'Mayor compromiso', 'Supremo', 'amarre', 90, 310000, null, '¿Sientes que esa persona no se decide contigo? ¿Te tiene en un “casi algo”, solo como amistad o como algo pasajero? Este ritual es la llave para transformar esa situación. Su energía actúa directamente en su mente y corazón. Con este trabajo, el vínculo deja de ser superficial: la persona siente con fuerza que eres la elección correcta, la pareja que le da estabilidad y seguridad.', 'Logra que', array['Deje atrás las dudas y la indecisión.', 'Te vea como prioridad y opción real de vida.', 'Sienta la necesidad de formalizar contigo y construir algo estable: desde un noviazgo hasta un compromiso serio.', 'Se rompan energías de confusión, miedo o deseo de tenerte “a medias”.']::text[], array[]::text[], false, true, 14) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('sello-de-amor-con-retorno', 'servicio', 'supremo', 'Sello de amor con retorno', 'Supremo', 'corazon', 220, 850000, null, 'Este poderoso ritual es la unión de seis fuerzas energéticas en un solo trabajo, diseñado para transformar y fortalecer tu relación. Además, tendrás la posibilidad de agregar hasta cinco peticiones personalizadas, enfocadas únicamente en tu relación, para que el trabajo se adapte a tus verdaderas necesidades y deseos.', 'Incluye', array['Retorno y ven a mí: atrae de vuelta a la persona amada, ya sea un ex o tu pareja actual, despertando en él/ella el deseo de regresar, buscarte y mantenerse atraído a ti.', 'Endulzamiento: suaviza pensamientos y emociones, generando ternura, cariño y acercamiento.', 'Deseo sexual: enciende la pasión y la atracción física, despertando la química entre ambos.', 'Atadura amorosa: refuerza el vínculo, haciendo que la persona no quiera alejarse de tu lado.', 'Potenciador de sentimientos: despierta, intensifica y reafirma sus sentimientos y emociones hacia ti.', 'Blindaje de pareja: protege la relación contra envidias, malas energías o terceras personas que quieran interferir.']::text[], array[]::text[], false, true, 15) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('dulce-obsesion', 'servicio', 'supremo', 'Dulce obsesión', 'Supremo', 'ojo', 140, 510000, null, 'Una combinación fuerte de cuatro trabajos energéticos que encenderán su deseo, apego y dependencia hacia ti. Este ritual es perfecto si quieres que esa persona se vuelva loca de amor por ti y no pueda imaginar su vida sin tenerte cerca.', 'Incluye', array['Vendaje de amor: hará que solo tenga ojos para ti, perdiendo el interés en cualquier otra persona.', 'Magnetismo: te volverás irresistible ante sus ojos, atrayéndolo como un imán.', 'Obsesión: su mente estará totalmente dominada por ti; no podrá dejar de pensarte, soñarte y anhelarte.', 'Pegado a mí: no querrá separarse de ti; se volverá pegajoso, deseando hacer todo contigo y necesitando tu presencia constante.']::text[], array[]::text[], false, true, 16) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('retorno-completo', 'servicio', 'supremo', 'Retorno completo', 'Supremo', 'llave', 155, 590000, null, 'Este trabajo actúa a nivel energético para alinear sus caminos, haciendo que su destino los vuelva a cruzar, ya sea por coincidencia o por una necesidad incontrolable de buscarte. Este ritual hará que, de una forma u otra, su destino sea encontrarse contigo.', 'Incluye', array['Retorno: provoca el regreso de la persona a tu vida, despertando el deseo de buscarte.', 'Desespero: genera ansiedad y desesperación, haciendo que no encuentre paz hasta estar contigo.', 'Endulzamiento: suaviza sus emociones, despertando su lado más dulce hacia ti.', 'Restauración de vínculo: sana bloqueos emocionales y resentimientos, permitiendo que la conexión se fortalezca.']::text[], array[]::text[], false, true, 17) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('endulzamiento-supremo', 'servicio', 'supremo', 'Endulzamiento supremo', 'Supremo', 'miel', 90, 330000, null, 'Eleva la conexión emocional, haciendo que la persona trabajada se vuelva más cariñosa. Si buscas una relación más amorosa, equilibrada y llena de momentos especiales, este ritual es para ti.', 'Incluye', array['Manzana de amor: endulza sus pensamientos y emociones, haciéndote más especial en su vida.', 'Endulzamiento: suaviza su carácter, fomentando una actitud más afectuosa y cercana.', 'Potencializador de sentimientos: refuerza y mantiene vivos los sentimientos positivos, asegurando una conexión estable y duradera.']::text[], array[]::text[], false, true, 18) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('rechaza-mozas', 'servicio', 'supremo', 'Rechaza mozas', 'Supremo', 'escudo', 90, 330000, null, '¿Tu pareja es mujeriego o tiene actitudes de infiel? Este poderoso ritual crea un escudo energético que hace que esas terceras personas sean rechazadas y apartadas de su camino. Con este trabajo, tu pareja deja de mirar a otras y se centra en lo que realmente importa: tu relación. Un ritual ideal para proteger lo tuyo y asegurar que nadie más logre interponerse.', 'Qué hace', array['Bloquea la influencia de mujeres entrometidas.', 'Evita coqueteos, tentaciones o distracciones.', 'Refuerza el enfoque de tu pareja únicamente hacia ti.']::text[], array[]::text[], false, true, 19) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('restauracion-completa-de-vinculo', 'servicio', 'supremo', 'Restauración completa de vínculo', 'Supremo', 'amarre', 110, 400000, null, 'Cuando una relación está llena de peleas constantes, envidias, energías negativas o simplemente ya no fluye como antes, este ritual combina dos fuerzas en un solo propósito.', 'Incluye', array['Limpieza de pareja: elimina cargas, brujerías, envidias y malas energías que contaminan la relación.', 'Sanación y restauración del vínculo: cierra heridas, rompe resentimientos y repara el lazo, devolviendo la confianza y la unión.']::text[], array[]::text[], false, true, 20) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('blindaje-de-vinculo', 'servicio', 'supremo', 'Blindaje de vínculo', 'Supremo', 'candado', 80, 290000, null, 'Este ritual crea un escudo energético que blinda tu relación (la protege) de interferencias externas, como malas energías o cualquier intención negativa hacia el vínculo. Si quieres blindar tu relación para que nadie pueda interferir en ella, este ritual es la mejor opción.', '¿Qué hace este ritual?', array['Bloquea energías negativas, envidias y chismes que puedan debilitar la relación.', 'Protege contra trabajos energéticos.']::text[], array[]::text[], false, true, 21) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('abre-camino-de-amor-supremo', 'servicio', 'supremo', 'Abre camino de amor supremo', 'Supremo', 'llave', 120, 400000, null, 'Este ritual es completamente personalizado, creado según lo que tú quieras manifestar en tu vida sentimental. Aquí tienes la oportunidad de pedir hasta 10 peticiones específicas, incluyendo no solo cualidades emocionales y de carácter, sino también rasgos físicos si así lo deseas. Este poderoso trabajo abre tus caminos en el amor y alinea tu energía con la pareja ideal, derribando bloqueos y atrayendo exactamente lo que deseas de manera natural y armoniosa.', 'Puedes intencionarlo con detalles como', array['Que sea hogareño, proveedor, fiel, amoroso, detallista.', 'Que tenga cierta apariencia física o estilo que te atraiga.', 'Que llegue a ti con la disposición de formar una relación estable y duradera.']::text[], array[]::text[], false, true, 22) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('triple-humillado', 'servicio', 'supremo', 'Triple humillado', 'Supremo', 'espejo', 100, 380000, null, 'Este ritual es ideal para quienes buscan el control total sobre una persona de carácter fuerte y orgulloso, logrando que se rinda ante ti con sumisión y arrepentimiento. Con este poderoso ritual lograrás que quien una vez te desafió ahora regrese humillado, suplicante y dispuesto a entregarse completamente a ti. Es especialmente efectivo cuando se combina con rituales de retorno.', 'Incluye', array['Doblegado a mí: rompe la terquedad y el orgullo, haciendo que reconozca sus errores y busque tu perdón genuinamente.', 'Humillado: hace que sienta remordimiento profundo por su actitud y acciones, sintiendo la necesidad de buscarte y rogar por tu atención.', 'Dominado: asegura que esta persona quede bajo tu influencia, obediente y receptiva a lo que le pidas, sin resistencia.']::text[], array[]::text[], false, true, 23) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('potencializador-de-sentimientos', 'servicio', 'supremo', 'Potencializador de sentimientos', 'Supremo', 'rosa', 80, 300000, null, 'Este ritual refuerza los sentimientos existentes entre dos personas. Es ideal cuando aún hay amor, pero todo parece estancado, apagado o frío. Reactiva la conexión emocional, suaviza tensiones y despierta nuevamente el vínculo, ayudando a que florezcan el cariño, la atención y las emociones sinceras. La persona comienza a mirarte con otros ojos, a recordarte con ternura y a volver a sentir cosas bonitas por ti, como si el amor renaciera.', null, array[]::text[], array[]::text[], false, true, 24) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('novena-personalizada', 'servicio', 'supremo', 'Novena personalizada', 'VIP', 'luna', 230, 900000, null, 'Este es el ritual más intenso y poderoso, diseñado a tu medida para obtener resultados definitivos. Durante nueve días consecutivos se trabajan distintas energías y rituales estratégicos según tu necesidad, combinando fuerza, seducción y dominio para asegurarte el control total de la situación. Perfecto para cuando quieres: amarrar a alguien sin escapatoria, recuperar un amor con desesperación y entrega absoluta, eliminar rivales de manera definitiva, atar a tu pareja con deseo y fidelidad inquebrantable, o cualquier intención que necesite un trabajo profundo y personalizado. Este es el trabajo más exclusivo y potente, diseñado para quienes buscan soluciones extremas y sin margen de error.', null, array[]::text[], array[]::text[], false, true, 25) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('amarre-de-corazon-con-las-siete-potencias-africanas', 'servicio', 'amarres', 'Amarre de corazón con las siete potencias africanas', 'Amarre', 'corazon', 430, null, null, 'Este ritual busca dominar emocionalmente a tu ser amado, utilizando el corazón de vaca como canal principal. Su energía crea una fuerte dependencia emocional y sexual, haciendo que esa persona no pueda alejarse de ti, generando una unión intensa y difícil de romper. Potenciado con la fuerza de las siete potencias (Eleguá, Oshún, Changó, Obatalá, Yemayá, Ogún y Orunmila). Este amarre incluye endulzamiento, atracción sexual, atadura, amarre y blindaje de pareja (ideal para casos difíciles). Solo se realiza en parejas que están juntas.', null, array[]::text[], array[]::text[], false, true, 26) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('amarre-matrimonial', 'servicio', 'amarres', 'Amarre matrimonial', 'Amarre', 'amarre', 300, null, null, 'Este es un amarre poderoso, diseñado para que tu pareja adquiera un compromiso serio y real contigo.', 'Incluye', array['Lluvia de detalles: se encargará tanto de las necesidades de tu corazón como de tus necesidades económicas.', 'Mayor compromiso: se comprometerá contigo y te hará parte de su vida.', 'Endulzamiento supremo + Potencializador de sentimientos: generando cariño constante y fortaleciendo sus sentimientos hacia ti.']::text[], array[]::text[], false, true, 27) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('amarre-negro', 'servicio', 'amarres', 'Amarre negro', 'Amarre', 'candado', 485, null, null, 'Está diseñado para dominar emocional y sexualmente a una persona; es agresivo para romper resistencias, eliminar interferencias y generar un apego obsesivo. Este trabajo es para las personas que buscan tener el control y el sometimiento emocional.', '¿Qué incluye?', array['Dominio', 'Retorno + ven a mí', 'Obsesión', 'Desespero macabro (mental y sexual)', 'Separación (eliminar a terceras personas)', 'Amarre']::text[], array[]::text[], false, true, 28) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('corte-de-lazos', 'servicio', 'cortes', 'Corte de lazos', 'Supremo', 'tijeras', 80, 290000, null, 'Está diseñado para romper el vínculo energético que te mantiene atado a una persona, liberándote de su influencia y permitiéndote avanzar sin cargas emocionales.', 'Ideal para cuando', array['Sientes que alguien te estanca o te hace sufrir, pero te cuesta alejarte.', 'A nivel sentimental, siempre terminas atrayendo el mismo tipo de persona.', 'Quieres cerrar ciclos y soltar a alguien con mayor facilidad.', 'Buscas paz emocional y una renovación en tu vida amorosa.']::text[], array[]::text[], false, true, 29) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('separacion', 'servicio', 'cortes', 'Separación', 'Supremo', 'tijeras', 170, 510000, null, 'Está diseñado para generar distanciamiento, conflictos y rupturas definitivas en una relación. Actúa sobre la energía de la pareja, debilitando su vínculo y fomentando desacuerdos hasta lograr la separación total. Ideal para cuando quieres que una pareja se aleje definitivamente, deseas que dos personas terminen su relación por conflictos, falta de amor o desgaste, buscas eliminar la conexión entre ellos para que tomen caminos distintos o necesitas acabar con una relación que consideras tóxica o dañina. Este trabajo es extremadamente poderoso y efectivo, asegurando que la separación sea natural y sin posibilidad de reconciliación.', null, array[]::text[], array[]::text[], false, true, 30) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('separacion-suprema', 'servicio', 'cortes', 'Separación suprema', 'Supremo', 'tijeras', 190, 710000, null, 'Separación por siete días: ritual de alta intensidad para cortar lazos afectivos entre dos personas. La velación se realiza durante siete días seguidos, lo que permite trabajar a profundidad sobre vínculos duraderos y relaciones estables con fuertes apegos emocionales. Provoca frialdad, discusiones, desapego emocional y quiebre del vínculo. Especialmente recomendado para relaciones largas que deseas disolver o alejar definitivamente de tu camino.', null, array[]::text[], array[]::text[], false, true, 31) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('hechizo-de-amor-propio', 'servicio', 'amorpropio', 'Hechizo de amor propio', 'Sencillo', 'rosa', 60, 200000, null, 'Reconexión contigo misma… es un acto de renacimiento. Este ritual está diseñado para ayudarte a reconectar con tu valor, sanar heridas emocionales, elevar tu autoestima y despertar el amor más importante: el tuyo. Ideal para quienes han olvidado cuánto merecen o han entregado tanto que se han vaciado. Aquí no solo te limpias: te reconoces, te eliges y te recuperas.', null, array[]::text[], array[]::text[], false, true, 32) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('autoendulzamiento', 'servicio', 'amorpropio', 'Autoendulzamiento', 'Sencillo', 'miel', 50, 180000, null, 'Un ritual poderoso para suavizar tu energía, reconectar con tu ternura y atraer miradas dulces… empezando por la tuya. Perfecto para esos momentos en los que sientes que te has perdido a ti misma, que has sido muy dura contigo o que necesitas reconectar con tu esencia femenina y sanadora.', null, array[]::text[], array[]::text[], false, true, 33) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('hechizo-de-belleza', 'servicio', 'amorpropio', 'Hechizo de belleza', 'Sencillo', 'espejo', 45, 170000, null, 'Resalta tu luz, potencia tu imagen. Un toque mágico para ayudarte a verte más linda, atractiva y segura. Este hechizo alinea tu energía con el cambio físico que deseas… pero recuerda: la verdadera transformación comienza contigo.', null, array[]::text[], array[]::text[], false, true, 34) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('magnetismo-personal', 'servicio', 'amorpropio', 'Magnetismo personal', 'Sencillo', 'luna', 45, 170000, null, 'Un trabajo sencillo pero efectivo, diseñado para elevar tu energía y activar tu poder de atracción natural. Ideal si quieres que las personas te noten, te busquen, te admiren y se sientan conectadas contigo sin esfuerzo. Este ritual despierta tu magnetismo interior, ayudándote a brillar con más fuerza, ya sea en el amor, el trabajo o en cualquier entorno donde quieras destacar.', null, array[]::text[], array[]::text[], false, true, 35) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('renacer-rosa', 'servicio', 'amorpropio', 'Renacer rosa', 'Supremo', 'rosa', 120, 400000, null, 'El ritual supremo de amor propio y renovación interior. Trabaja profundamente en tu autoestima, sanación emocional y seguridad personal. Disuelve heridas antiguas, limpia tu energía de apegos dolorosos y fortalece tu identidad. Con Renacer rosa floreces desde dentro, recuperas tu poder, tu dulzura y tu magnetismo natural, y creas una versión de ti misma que no se conforma con menos de lo que merece. Este ritual te prepara para amarte con conciencia, irradiar tu luz auténtica y atraer personas, experiencias y caminos que vibran en el amor y la abundancia.', null, array[]::text[], array[]::text[], false, true, 36) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('esencia-perfecta', 'servicio', 'amorpropio', 'Esencia perfecta', 'Supremo', 'espejo', 80, 300000, null, 'Un ritual diseñado para armonizar tu energía interna y potenciar lo mejor de ti por dentro y por fuera. Este trabajo mágico combina autoendulzamiento, salud y belleza, generando un efecto integral que embellece tu campo energético, atrae bienestar físico y emocional, y eleva tu amor propio. Es ideal si deseas iniciar un glow up, sentirte más segura, verte y proyectarte mejor. No es solo estética: es autoestima, es energía renovada, es verte como siempre has soñado… y que el mundo también lo note. Este ritual es completamente personalizado.', null, array[]::text[], array[]::text[], false, true, 37) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('magnetismo-irresistible', 'servicio', 'amorpropio', 'Magnetismo irresistible', 'Supremo', 'luna', 100, 350000, null, 'Ritual combinado de Seductora suprema + Todos tras de mí. Despierta una atracción poderosa y despiadada a tu alrededor. Esta combinación trabaja tu sensualidad, tu seguridad y tu aura, convirtiéndote en una presencia inolvidable. No solo te verán más deseable, sino que sentirán la necesidad de buscarte, pensarte, acercarse y quedarse. Ideal para quienes quieren destacar, ser el centro de atención y tener el control total del deseo que provocan.', null, array[]::text[], array[]::text[], false, true, 38) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('fuerza-salvaje-de-lilith', 'servicio', 'amorpropio', 'Fuerza salvaje de Lilith', 'Supremo', 'luna', 110, 400000, null, 'Un ritual de amor propio y belleza que actúa como un pacto espiritual con Lilith, la energía femenina indomable, libre y profundamente sensual. Este trabajo mágico te conecta con tu fuerza interior, despierta tu autoestima, activa tu magnetismo natural y te ayuda a romper con culpas, limitaciones o miedos impuestos. Ideal para mujeres que desean amarse sin censura, reclamar su poder personal y sentirse irresistibles desde su autenticidad.', null, array[]::text[], array[]::text[], false, true, 39) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('encanto-de-afrodita', 'servicio', 'amorpropio', 'Encanto de Afrodita', 'Supremo', 'rosa', 110, 400000, null, 'Invoca la energía amorosa, dulce y magnética de Afrodita para irradiar belleza, carisma y atracción a todos los niveles. No solo te hace ver más hermosa, sino que también eleva tu amor propio, tu dulzura interna y tu poder para atraer amor sincero y admiración genuina.', null, array[]::text[], array[]::text[], false, true, 40) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('congelamiento-de-corazon', 'servicio', 'amorpropio', 'Congelamiento de corazón', 'Supremo', 'cuarzo', 80, 280000, null, 'Congela y neutraliza toda energía negativa, recuerdos dolorosos o emociones que te atan al pasado. Protege tu corazón de futuras heridas, cerrando ciclos con amor pero con firmeza. Es ideal para quien necesita alejar apegos tóxicos y fortalecer su sanación emocional de manera definitiva.', null, array[]::text[], array[]::text[], false, true, 41) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('tesoro-abierto', 'servicio', 'abundancia', 'Tesoro abierto', 'Sencillo', 'monedas', 50, 190000, null, 'Este ritual está diseñado para potenciar y multiplicar tus ingresos. Si sientes que el dinero no fluye como debería, este trabajo canaliza la energía de la abundancia para que el dinero llegue a ti de forma constante y creciente.', null, array[]::text[], array[]::text[], false, true, 42) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('iman-de-clientes', 'servicio', 'abundancia', 'Imán de clientes', 'Sencillo', 'maletin', 45, 180000, null, 'Si tu negocio está estancado o las ventas no fluyen como quieres, este ritual es la clave. Atrae clientes constantes, activa el deseo de compra y potencia la energía de prosperidad en tu emprendimiento. No dejes que la competencia te opaque: conviértete en un imán de abundancia.', null, array[]::text[], array[]::text[], false, true, 43) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('abre-camino-general', 'servicio', 'abundancia', 'Abre camino general', 'Sencillo', 'llave', 60, 200000, null, 'Cuando todo parece estancado, este ritual sencillo pero efectivo despeja el camino en el amor, el dinero, la suerte y la vida en general. Remueve bloqueos, libera la energía y permite que las oportunidades lleguen a ti sin interferencias. ¡Abre la puerta a lo que mereces!', null, array[]::text[], array[]::text[], false, true, 44) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('abre-camino-laboral', 'servicio', 'abundancia', 'Abre camino laboral', 'Sencillo', 'maletin', 45, 180000, null, 'Este ritual desbloquea oportunidades y atrae el crecimiento laboral que mereces. Sin embargo, la magia abre puertas, pero tú debes cruzarlas. Es fundamental que también tomes acción: busca, postula y muévete. La energía se alineará a tu favor, pero el esfuerzo es clave para que la oportunidad llegue y se materialice.', null, array[]::text[], array[]::text[], false, true, 45) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('suerte-rapida', 'servicio', 'abundancia', 'Suerte rápida', 'Sencillo', 'trebol', 45, 180000, null, 'Este ritual está diseñado para potenciar tu suerte de manera inmediata, alineando la energía a tu favor en juegos de azar, apuestas y cualquier situación donde necesites un golpe de fortuna. No garantiza ganancias fijas, pero sí maximiza tus posibilidades de éxito, abriendo caminos para que la suerte te favorezca en el momento justo.', null, array[]::text[], array[]::text[], false, true, 46) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('lluvia-de-dinero-llave-de-la-fortuna', 'servicio', 'abundancia', 'Lluvia de dinero + Llave de la fortuna', 'VIP', 'monedas', 90, 310000, null, 'Lluvia de dinero: te conecta con flujos de prosperidad inesperados: pagos retenidos, ventas rápidas, dinero que parecía perdido… y que ahora regresa a ti con fuerza. Llave de la fortuna: desbloquea las puertas de la abundancia, permitiendo que la prosperidad fluya desde todos los rincones del universo.', null, array[]::text[], array[]::text[], true, true, 47) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('hechizo-rapido-de-la-prosperidad', 'servicio', 'abundancia', 'Hechizo rápido de la prosperidad', 'Supremo', 'trebol', 70, 210000, null, 'Cuando la necesidad es urgente, este trabajo actúa como un impulso energético para abrir caminos inmediatos hacia el dinero. Ideal para saldar deudas, cubrir imprevistos o lograr una entrada rápida de efectivo. Acciona el flujo de prosperidad y permite que el universo responda sin demora. No es un milagro, es magia dirigida con intención.', null, array[]::text[], array[]::text[], false, true, 48) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('negocio-dorado-blindado', 'servicio', 'abundancia', 'Negocio dorado blindado', 'Supremo', 'escudo', 70, 210000, null, 'Ritual “Imán de clientes y protección financiera”. Atrae, retén y protege lo que es tuyo. Este ritual trabaja en doble línea: por un lado, activa tu energía de magnetismo comercial para atraer más clientes, ventas y oportunidades. Por el otro, establece una barrera protectora sobre tu negocio, tus ingresos y tus finanzas, bloqueando envidias, bloqueos energéticos y pérdidas económicas. Ideal para quienes tienen un emprendimiento, tienda o prestan servicios y sienten que algo los frena o drena su crecimiento. Un ritual que no solo llama el dinero… también lo retiene y lo defiende.', null, array[]::text[], array[]::text[], false, true, 49) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('desbloqueo-total', 'servicio', 'abundancia', 'Desbloqueo total', 'Supremo', 'llave', 100, 350000, null, 'No todos los caminos se abren con la misma llave… por eso este ritual es personalizado exclusivamente para ti. Analizo tu caso de forma individual, canalizo tu energía y creo un trabajo a medida, único e irrepetible. Un ritual exclusivo de alta magia, diseñado para romper ataduras energéticas, abrir portales de cambio y activar la verdadera fluidez en tu vida. Este no es un trabajo común, es un destrabe profundo para almas que sienten que TODO se les complica: relaciones que no avanzan, dinero que no fluye, puertas que se cierran, caminos bloqueados. Aquí no pedimos permiso, intervenimos con poder en cada área estancada. Ideal para quienes ya lo han intentado todo y sienten que algo más grande los está bloqueando. Desbloqueo total no es para cualquiera… es para quienes están listos para que TODO cambie.', null, array[]::text[], array[]::text[], false, true, 50) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('impulso-laboral-supremo', 'servicio', 'abundancia', 'Impulso laboral supremo', 'Supremo', 'maletin', 80, 250000, null, 'No es solo conseguir un trabajo… es abrir el camino hacia el trabajo soñado, el ascenso que mereces o ese aumento de sueldo que tanto te has ganado. Este ritual supremo está diseñado para personas que no se conforman con lo básico, sino que desean avanzar, brillar y ocupar el lugar que les corresponde. Combina desbloqueo energético, activación de oportunidades laborales específicas y alineación con la frecuencia del éxito profesional. Un ritual completamente personalizado, creado según tu campo, tus metas y tu energía actual. Ideal si sientes que has llegado a un techo, te estancas en lo mismo o tu talento no está siendo valorado.', null, array[]::text[], array[]::text[], false, true, 51) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('novena-personalizada-de-la-prosperidad', 'servicio', 'abundancia', 'Novena personalizada de la prosperidad', 'VIP', 'luna', 200, 750000, null, '9 días… 9 golpes de poder directo al universo. No es un simple ritual, es un proceso energético diario donde potencio tu intención hasta volverla imparable. ¿Quieres atraer dinero rápido? ¿Clientes? ¿Un mejor sueldo? ¿Suerte en juegos? ¿Trabajo ideal? Elige el ritual de abundancia que necesitas y yo me encargo de llevarlo al máximo nivel. Durante nueve días, tu petición arderá en mi altar como un decreto al universo. Aquí no se desea… ¡se manifiesta con fuerza!', null, array[]::text[], array[]::text[], false, true, 52) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('cheque-magico-del-universo', 'servicio', 'abundancia', 'Cheque mágico del universo', 'Supremo', 'cheque', 50, 180000, null, 'Una intención clara, un llamado a la abundancia. Este ritual simbólico te invita a escribir, con convicción y fe, la cifra económica que crees merecer. Al plasmar ese número en tu cheque, estás enviando un mensaje directo al universo: “Estoy listo para recibir”. El universo, en su infinita sabiduría, comenzará a moverse a tu favor. Puede que ese dinero llegue en formas inesperadas: pagos atrasados que aparecen, ventas que fluyen con facilidad, oportunidades nuevas o incluso dinero encontrado de forma mágica.', null, array[]::text[], array[]::text[], false, true, 53) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('ritual-de-limpieza-general', 'servicio', 'limpieza', 'Ritual de limpieza general', 'Sencillo', 'escoba', 60, 200000, null, 'Un trabajo energético pensado para aligerar tu carga, soltar tensiones acumuladas y renovar tu energía desde lo profundo. Ideal si sientes que todo pesa más de lo normal, que las cosas no fluyen como antes o simplemente necesitas un respiro para volver a conectar contigo. Este ritual te ayuda a sentirte más liviano, centrado y con la mente clara, abriendo espacio para nuevas oportunidades, decisiones firmes y bienestar emocional.', null, array[]::text[], array[]::text[], false, true, 54) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('ritual-de-limpieza-mental', 'servicio', 'limpieza', 'Ritual de limpieza mental', 'Sencillo', 'hierbas', 40, 160000, null, 'Cuando tu mente no para, los pensamientos abruman y sientes que todo te sobrepasa… este ritual es un respiro. Limpia tu campo mental de cargas, pensamientos repetitivos y bloqueos emocionales, devolviéndote la calma, la claridad y la ligereza. No es una solución clínica, pero sí un poderoso refuerzo energético para quienes están atravesando momentos de saturación mental o emocional. Ideal para acompañar procesos terapéuticos o reconectar contigo.', null, array[]::text[], array[]::text[], false, true, 55) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('ritual-de-memoria-sexual', 'servicio', 'limpieza', 'Ritual de memoria sexual', 'Sencillo', 'tijeras', 45, 170000, null, 'Dicen que el cuerpo olvida, pero la energía no. Cada encuentro sexual deja huellas… y muchas veces, esas huellas no nos pertenecen. Este ritual corta lazos energéticos sexuales con antiguas parejas, limpiando memorias kármicas que pueden permanecer hasta 7 años en tu campo áurico. Libérate de influencias ajenas, recupera tu energía vital y devuelve el control de tu cuerpo, tu deseo y tu magnetismo. Ideal para quienes sienten que aún cargan con recuerdos, sensaciones o bloqueos que no son suyos.', null, array[]::text[], array[]::text[], false, true, 56) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('ritual-de-limpieza-energetica-para-mascotas', 'servicio', 'limpieza', 'Ritual de limpieza energética para mascotas', 'Sencillo', 'pata', 35, 150000, null, 'Mucho más que un acto simbólico, este ritual está diseñado para eliminar energías densas, emociones absorbidas del entorno y cargas espirituales que afectan el comportamiento o el bienestar de tu mascota. Ellos, al ser seres sensibles, captan vibraciones que nosotros no percibimos. Este trabajo actúa como un reinicio energético que los ayuda a recuperar su equilibrio natural, descansar mejor y sentirse más tranquilos. Ideal si tu mascota ha pasado por un proceso difícil, ha estado en contacto con personas o lugares cargados, o simplemente deseas brindarle un cuidado energético profundo y amoroso. Complementa perfectamente la atención veterinaria con un enfoque holístico y espiritual.', null, array[]::text[], array[]::text[], false, true, 57) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('despojo-de-ojos-negros', 'servicio', 'limpieza', 'Despojo de ojos negros', 'Sencillo', 'ojo', 50, 180000, null, 'Un ritual profundamente depurativo, diseñado para cortar las energías densas provocadas por el mal de ojo, la envidia silenciosa y las cargas proyectadas por miradas malintencionadas. Este trabajo actúa como un escudo espiritual, liberando el campo energético de interferencias que entorpecen tu bienestar, tu éxito y tu paz interior. Ideal para quienes se sienten drenados sin razón aparente, experimentan bloqueos repentinos o sienten presencias pesadas tras exponerse demasiado. Una limpieza potente para recuperar tu brillo, tu fuerza… y tu rumbo.', null, array[]::text[], array[]::text[], true, true, 58) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('limpieza-y-despojo-supremo', 'servicio', 'limpieza', 'Limpieza y despojo supremo', 'Supremo', 'escoba', 120, 400000, null, 'Es una purga energética de alto nivel. Este ritual rompe con cargas pesadas, elimina residuos de trabajos anteriores, corta energías ajenas y te devuelve tu poder personal. Es un reinicio profundo para quienes sienten que nada avanza, que todo les pesa o que algo invisible los frena. Ideal después de crisis, rupturas, traiciones o etapas densas.', null, array[]::text[], array[]::text[], false, true, 59) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('barrido-de-bruja-tumba-trabajo', 'servicio', 'limpieza', 'Barrido de bruja + tumba trabajo', 'Supremo', 'escoba', 150, 550000, null, 'Ritual poderoso para cortar, limpiar y liberar. Combina el Barrido de bruja con el Tumba trabajo, creado para tumbar y deshacer cualquier tipo de brujería, hechizos, maldiciones o trabajos oscuros. Actúa como una limpieza profunda que corta lazos energéticos negativos y elimina toda carga pesada que no se va con métodos comunes. Ideal para ti si sientes estancamiento, agotamiento, presencias oscuras o sabes que te han trabajado.', 'Incluye', array['Disolución total de trabajos de brujería', 'Limpieza energética avanzada', 'Corte de lazos y rastros mágicos']::text[], array[]::text[], false, true, 60) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('ritual-de-liberacion-emocional', 'servicio', 'limpieza', 'Ritual de liberación emocional', 'Supremo', 'hierbas', 80, 280000, null, 'Un trabajo energético profundo para ayudarte a soltar cargas del pasado: relaciones que aún duelen, emociones reprimidas, heridas que aún pesan. Este ritual no borra la historia, pero corta los lazos que te mantienen atado al dolor, permitiéndote avanzar con más ligereza y claridad. Ideal para quienes sienten que ya es momento de sanar y dejar atrás lo que ya no les pertenece.', null, array[]::text[], array[]::text[], false, true, 61) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('refuerzo-para-tu-salud', 'servicio', 'limpieza', 'Refuerzo para tu salud', 'Supremo', 'vela', 80, 280000, null, 'Un ritual energético diseñado como apoyo espiritual para quienes atraviesan malestares físicos o emocionales. No sustituye atención médica ni terapias, pero trabaja a nivel energético para aportar fuerza, equilibrio y bienestar. Ideal para quienes sienten su cuerpo o mente debilitados y buscan un impulso extra de luz en su proceso de recuperación.', null, array[]::text[], array[]::text[], false, true, 62) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('blindaje-energetico', 'servicio', 'proteccion', 'Blindaje energético', 'Sencillo', 'escudo', 45, 170000, null, 'Un ritual de alta protección diseñado para reforzar tu campo áurico y sellar tu energía ante cualquier intento de manipulación, desgaste o ataque psíquico. Este trabajo crea una barrera energética resistente que impide el ingreso de vibraciones negativas, celos, pensamientos intrusivos o cualquier energía no deseada que interfiera en tu camino. Ideal para quienes están expuestos constantemente a ambientes cargados, envidias, o simplemente desean proteger su energía en procesos importantes de su vida. Una armadura invisible pero poderosa, que te mantiene firme, centrado y protegido.', null, array[]::text[], array[]::text[], false, true, 63) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('proteccion-laboral', 'servicio', 'proteccion', 'Protección laboral', 'Sencillo', 'maletin', 45, 170000, null, 'Un ritual creado para resguardar tu estabilidad en el entorno de trabajo. Ideal si te sientes expuesto a envidias, rumores, sabotajes o simplemente deseas proteger lo que has logrado. Este trabajo fortalece tu presencia profesional, disuelve malas intenciones a tu alrededor y crea un escudo energético que impide que energías externas interfieran en tu rendimiento, oportunidades o reputación. Recomendado tanto para quienes están en cargos importantes como para quienes han conseguido empleo recientemente y quieren conservarlo sin interferencias.', null, array[]::text[], array[]::text[], false, true, 64) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('ritual-de-proteccion-energetica-para-mascotas', 'servicio', 'proteccion', 'Ritual de protección energética para mascotas', 'Sencillo', 'pata', 35, 150000, null, 'Nuestras mascotas no solo son compañía: también son receptores sensibles de la energía que nos rodea. En muchos casos pueden absorber cargas negativas dirigidas hacia nosotros, ser canal de trabajos espirituales o incluso enfermar sin explicación aparente por recoger malas intenciones o brujerías que no eran para ellas, sino para sus dueños. Este ritual actúa como escudo protector, liberando a tu mascota de cualquier energía ajena que esté interfiriendo en su bienestar y blindándola contra futuras influencias dañinas.', null, array[]::text[], array[]::text[], false, true, 65) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('consagracion-de-amuletos', 'servicio', 'proteccion', 'Consagración de amuletos', 'Sencillo', 'cuarzo', 30, 120000, null, 'Activa el verdadero poder de tu amuleto con este ritual personalizado. Lo realizamos por videollamada, con los elementos que te indicaré. Ideal para protección, abundancia o sanación. Un objeto deja de ser solo materia cuando se despierta su energía mágica.', null, array[]::text[], array[]::text[], false, true, 66) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('despedida-eterna', 'servicio', 'proteccion', 'Despedida eterna', 'Supremo', 'tijeras', 100, 350000, null, 'Es un ritual de liberación y destierro. Cuando alguien no te deja en paz, insiste en quedarse en tu vida o te acosa emocionalmente, este ritual corta su influencia y lo aleja definitivamente de ti. Ideal para ex parejas, enemigos, acosadores o personas tóxicas que quieres fuera de tu vida y de tu entorno. ¡Recupera tu libertad, tu paz y tu poder personal de una vez por todas!', 'Este ritual incluye', array['Limpieza energética profunda.', 'Corte de lazo y destierro.', 'Protección y sellado espiritual.']::text[], array[]::text[], false, true, 67) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('blindaje-supremo', 'servicio', 'proteccion', 'Blindaje supremo', 'Supremo', 'escudo', 120, 400000, null, 'Una protección energética de élite. Este ritual crea un escudo impenetrable alrededor de tu campo áurico, blindándote contra energías invasivas, malintencionadas o de baja vibración. Ideal para quienes están expuestos constantemente al mal de ojo, la envidia, la brujería o el desgaste espiritual. No solo protege… eleva tu vibración para que nada negativo te toque.', null, array[]::text[], array[]::text[], false, true, 68) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('proteccion-defensiva', 'servicio', 'proteccion', 'Protección defensiva', 'Supremo', 'escudo', 130, 510000, null, 'Este ritual ha sido creado para quienes sienten que están siendo tocados por energías externas: envidias, brujerías, malos pensamientos o simplemente presencias que no deberían estar cerca. No solo protege… bloquea, rebota y devuelve cualquier intento de daño, brujería o mala intención. Es una defensa activa, hecha para quienes no se van a quedar de brazos cruzados mientras su energía es drenada o manipulada.', null, array[]::text[], array[]::text[], false, true, 69) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('volteo-de-espejo', 'servicio', 'proteccion', 'Volteo de espejo', 'Supremo', 'espejo', 120, 400000, null, 'Este ritual actúa como un escudo de alto impacto: cualquier brujería, mala intención o daño enviado hacia ti es devuelto a su origen. Trabaja con el poder del espejo como símbolo de reflejo y justicia energética, sin necesidad de agredir, solo permitiendo que cada quien reciba lo que ha emitido. Ideal para personas que sienten ataques constantes, bloqueos sin explicación o presencias pesadas en su entorno. Lo que envíen, lo recibirán. Aquí, la energía se equilibra sola.', null, array[]::text[], array[]::text[], false, true, 70) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('botella-de-bruja', 'servicio', 'proteccion', 'Botella de bruja', 'Supremo', 'botella', 90, 320000, null, 'Un antiguo y poderoso ritual de protección, sellado y contención energética. Esta botella es preparada de manera personalizada con elementos consagrados, símbolos de poder y cargas mágicas específicas según tu caso. Su función es atrapar, bloquear y alejar energías negativas, personas malintencionadas o influencias que estén afectando tu paz, tu suerte o tu entorno. También puede ser programada para proteger relaciones, negocios, viviendas o caminos personales.', null, array[]::text[], array[]::text[], false, true, 71) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('proteccion-familiar', 'servicio', 'proteccion', 'Protección familiar', 'Supremo', 'escudo', 120, null, null, '', null, array[]::text[], array[]::text[], false, true, 72) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('vela-de-refuerzo', 'servicio', 'velas', 'Vela de refuerzo', 'Amor', 'vela', 30, 60000, null, 'Tiene como propósito potenciar el trabajo de amor, ya sea para acelerar sus efectos o, en caso de que ya haya surtido efecto, revitalizar su energía, ya que con el tiempo podría haber perdido intensidad. No sería necesario repetir el mismo ritual sin antes realizar un refuerzo con la vela. Así mismo, si el trabajo está tardando en manifestar resultados, puedes reforzarlo tantas veces como consideres necesario para fortalecer su influencia.', null, array[]::text[], array[]::text[], false, true, 73) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('vela-de-refuerzo-vip', 'servicio', 'velas', 'Vela de refuerzo VIP', 'VIP', 'velas', 50, 150000, null, 'La vela definitiva para potenciar y amplificar cualquier trabajo. Más grande, intensa y con una carga mágica superior, diseñada para acelerar resultados, romper bloqueos y fortalecer el poder del ritual. Si el trabajo ha perdido fuerza, esta vela lo revitaliza e impulsa al siguiente nivel. No repitas el ritual sin antes reforzarlo con su energía de alto impacto. Ideal para manifestaciones rápidas y contundentes, garantiza que la energía fluya sin interrupciones. También perfecta para hacer peticiones o manifestar deseos con máxima intensidad.', null, array[]::text[], array[]::text[], false, true, 74) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('vela-de-refuerzo-super-vip', 'servicio', 'velas', 'Vela de refuerzo super VIP', 'VIP', 'velas', 100, 360000, null, 'El impulso más poderoso para que tu ritual no se detenga. Potencia, acelera y multiplica la energía, llevándola directo a la manifestación. Exclusiva, intensa y cargada de poder: ¡la chispa que convierte tu petición en realidad!', null, array[]::text[], array[]::text[], false, true, 75) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('velita-potencializadora-amor-propio', 'servicio', 'velas', 'Velita potencializadora (amor propio)', 'Amor propio', 'vela', 20, 50000, null, '', 'Beneficios', array['Aceleradora de efectos en rituales', 'Refuerzo energético personalizado', 'Eleva tu vibración emocional', 'Te ayuda a sentirte más bonita y segura', 'Ideal para atraer buena energía en la semana', 'Perfecta para darte un cuidado espiritual consciente']::text[], array[]::text[], false, true, 76) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('velita-potencializadora-suprema-amor-propio', 'servicio', 'velas', 'Velita potencializadora suprema (amor propio)', 'Amor propio', 'vela', 30, 80000, null, 'Es la llave secreta que impulsa cualquier trabajo espiritual hacia su máximo poder. Aumenta la fuerza, acelera resultados y refuerza cada intención que estés trabajando. La puedes usar como acompañamiento en rituales importantes para sellar y fortalecer aún más tus peticiones.', null, array[]::text[], array[]::text[], false, true, 77) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('velon-de-los-deseos', 'servicio', 'velas', 'Velón de los deseos', 'Amor propio', 'velas', 50, 180000, null, 'Este velón consagrado es el canal perfecto para materializar tus intenciones más profundas. Carga de energía tu petición y la envía al universo de manera potente, acelerando la apertura de caminos y la manifestación de tus deseos en el plano material.', null, array[]::text[], array[]::text[], false, true, 78) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('velita-potencializadora-abundancia', 'servicio', 'velas', 'Velita potencializadora (abundancia)', 'Abundancia', 'vela', 30, 60000, null, 'Sirve para acelerar rituales y manifestaciones. Refuerza peticiones, rompe estancamientos y canaliza la energía con precisión hacia tu objetivo.', null, array[]::text[], array[]::text[], false, true, 79) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('vela-potencializadora-suprema-abundancia', 'servicio', 'velas', 'Vela potencializadora suprema (abundancia)', 'Abundancia', 'velas', 50, 150000, null, 'Esta vela no solo acelera la energía de tus rituales… también es una herramienta mágica independiente, capaz de tomar un deseo claro y dirigirlo con intensidad al universo. Ya sea que quieras usarla como refuerzo de otro trabajo o como canalizador de una petición específica, su energía se adapta a ti. Ideal para cuando necesitas que algo se manifieste más rápido o simplemente deseas darle más fuerza y dirección a lo que tu corazón anhela. Importante: escríbeme tu intención para que la vela sea programada especialmente con tu energía.', null, array[]::text[], array[]::text[], false, true, 80) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('velita-potencializadora-de-limpieza', 'servicio', 'velas', 'Velita potencializadora de limpieza', 'Limpieza', 'vela', 20, 50000, null, 'Esta vela actúa como un impulso extra en tus trabajos de limpieza energética, ayudando a remover cargas, liberar bloqueos y despejar tu campo espiritual de residuos negativos. Ideal para quienes sienten que algo aún persiste tras una limpieza o desean que su ritual tenga un efecto más profundo y duradero. Se adapta a cualquier tipo de trabajo de purificación, elevando su potencia y acelerando los resultados.', null, array[]::text[], array[]::text[], false, true, 81) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('velita-potencializadora-suprema-limpieza', 'servicio', 'velas', 'Velita potencializadora suprema (limpieza)', 'Limpieza', 'vela', 30, 80000, null, 'Una herramienta mágica exclusiva para quienes trabajan con rituales de alta intensidad. Esta vela limpia interferencias, potencia la energía del ritual principal y lo alinea con tu intención más profunda. Ideal para desbloquear procesos lentos, reforzar trabajos personalizados o cuando necesitas resultados más estables y duraderos.', null, array[]::text[], array[]::text[], false, true, 82) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('ritual-personalizado-de-amor', 'servicio', 'personalizado', 'Ritual personalizado de amor', 'VIP', 'corazon', null, null, 'Desde 300 USD', '¿Tienes una situación única y compleja que no encaja en ningún ritual tradicional? Este trabajo está hecho a tu medida. Analizo tu caso a profundidad, diseño un ritual exclusivo y me dedico completamente a su ejecución, sin distracciones y con prioridad total. Ideal para casos delicados, situaciones límite o donde necesitas resultados claros y directos. Ritual exclusivo, único y enfocado solo en tu caso. Valor estimado: 300 USD en adelante, dependiendo de tu situación.', null, array[]::text[], array[]::text[], false, true, 83) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('ritual-personalizado-de-amor-propio', 'servicio', 'personalizado', 'Ritual personalizado de amor propio', 'VIP', 'rosa', null, null, 'Desde 100 USD', '¿Tienes una situación única y compleja que no encaja en ningún ritual tradicional? Este trabajo está hecho a tu medida. Analizo tu caso a profundidad, diseño un ritual exclusivo y me dedico completamente a su ejecución, sin distracciones y con prioridad total. Ideal para casos delicados, situaciones límite o donde necesitas resultados claros y directos. Ritual exclusivo, único y enfocado solo en tu caso. Valor estimado a partir de 100 USD. El precio final depende de la dificultad, materiales y carga energética del caso. (Puedes consultarme sin compromiso y te doy una valoración honesta y detallada.)', null, array[]::text[], array[]::text[], false, true, 84) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('ritual-personalizado-de-limpieza-y-proteccion', 'servicio', 'personalizado', 'Ritual personalizado de limpieza y protección', 'VIP', 'escudo', null, null, 'Desde 100 USD', '¿Tienes una situación única y compleja que no encaja en ningún ritual tradicional? Este trabajo está hecho a tu medida. Analizo tu caso a profundidad, diseño un ritual exclusivo y me dedico completamente a su ejecución, sin distracciones y con prioridad total. Ideal para casos delicados, situaciones límite o donde necesitas resultados claros y directos. Ritual exclusivo, único y enfocado solo en tu caso. Valor estimado a partir de 100 USD. El precio final depende de la dificultad, materiales y carga energética del caso. (Puedes consultarme sin compromiso y te doy una valoración honesta y detallada.)', null, array[]::text[], array[]::text[], false, true, 85) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('ritual-personalizado-de-abundancia', 'servicio', 'personalizado', 'Ritual personalizado de abundancia', 'VIP', 'monedas', null, null, 'Desde 300 USD', 'El valor de este ritual se estima a partir de 300 USD. El precio final depende de la dificultad, materiales y carga energética del caso. (Puedes consultarme sin compromiso y te doy una valoración honesta y detallada.)', null, array[]::text[], array[]::text[], false, true, 86) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('lectura-de-tarot', 'servicio', 'tarot', 'Lectura de tarot', 'Lectura', 'tarot', null, null, null, 'Todo trabajo de amor requiere previa lectura para conocer y comprender a profundidad los sentimientos de la persona y la situación en la que se encuentran.', null, array[]::text[], array[]::text[], false, true, 87) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('corazon-encantado', 'producto', 'pociones', 'Corazón encantado', 'Producto', 'pocima', 40, 150000, null, 'Pócima encantada de amor propio y autoendulzamiento. Este amuleto ha sido preparado y consagrado con una mezcla especial de energías para ayudarte a conectar con tu amor propio, dulzura interior y poder femenino. No solo te acompaña energéticamente, sino que actúa como un recordatorio constante de lo que eres y mereces. Puede potencializarse con un ritual de amor propio, creando una armonización poderosa que refuerza tu brillo y bienestar emocional desde adentro.', null, array[]::text[], array[]::text[], false, true, 0) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('pocima-perfecta', 'producto', 'pociones', 'Pócima perfecta', 'Producto', 'pocima', 60, 200000, null, 'Una esencia preparada y ritualizada con intención para activar tu amor propio, realzar tu belleza interna y atraer lo que mereces: miradas, oportunidades y abundancia. Llévala contigo como amuleto diario o colócala en tu altar como fuente de poder constante. Si estás en Colombia y así lo deseas, puedo hacerte el envío físico del frasco. Si te encuentras en otro país, lo entierro en una maceta especial, activando su poder de igual manera para que continúe cumpliendo su función sin perder efectividad.', null, array[]::text[], array[]::text[], false, true, 1) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('pulsera-de-proteccion', 'producto', 'pulseras', 'Pulsera de protección', 'Producto', 'pulsera', null, null, null, '', null, array[]::text[], array[]::text[], false, false, 2) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('pulsera-de-hilo-rojo', 'producto', 'pulseras', 'Pulsera de hilo rojo', 'Producto', 'pulsera', null, null, null, '', null, array[]::text[], array[]::text[], false, false, 3) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('amuleto-consagrado', 'producto', 'amuletos', 'Amuleto consagrado', 'Producto', 'cuarzo', null, null, null, '', null, array[]::text[], array[]::text[], false, false, 4) on conflict (slug) do nothing;
insert into public.items (slug, tipo, seccion, nombre, nivel, motivo, precio_usd, precio_cop, precio_texto, descripcion, incluye_titulo, incluye, palabras_clave, destacado, visible, orden) values ('cuarzo-rosa', 'producto', 'amuletos', 'Cuarzo rosa', 'Producto', 'cuarzo', null, null, null, '', null, array[]::text[], array[]::text[], false, false, 5) on conflict (slug) do nothing;
insert into public.preguntas (clave, pregunta, respuesta, palabras_clave, aplica_a, emocion, acciones, orden) values ('garantia', '¿Los trabajos tienen garantía?', 'Todo trabajo energético cuenta con una garantía de tres meses, siempre y cuando se haya realizado al menos una vela de refuerzo y haya actualizaciones constantes sobre el avance del trabajo. Si se cumplen estos requisitos y no se han visto resultados, haré otro ritual por mi cuenta. De lo contrario, no me hago responsable.', array['garantia', 'garantizado', 'si no funciona', 'resultados', 'seguro']::text[], array['general']::text[], 'hablando', '[]'::jsonb, 0) on conflict (clave) do nothing;
insert into public.preguntas (clave, pregunta, respuesta, palabras_clave, aplica_a, emocion, acciones, orden) values ('pago-adelantado', '¿Cuándo se paga el trabajo?', 'Todo trabajo se paga por adelantado al momento de apartar tu cupo.', array['pago', 'pagar', 'adelantado', 'anticipo', 'cupo', 'apartar']::text[], array['general']::text[], 'hablando', '[]'::jsonb, 1) on conflict (clave) do nothing;
insert into public.preguntas (clave, pregunta, respuesta, palabras_clave, aplica_a, emocion, acciones, orden) values ('devoluciones', '¿Hay devoluciones?', 'No hay devoluciones: todos los trabajos energéticos requieren un intercambio y, una vez realizado el pago, no hay devoluciones.', array['devolucion', 'reembolso', 'devolver dinero', 'cancelar']::text[], array['general']::text[], 'apenada', '[]'::jsonb, 2) on conflict (clave) do nothing;
insert into public.preguntas (clave, pregunta, respuesta, palabras_clave, aplica_a, emocion, acciones, orden) values ('tiempo-resultados', '¿Cuánto tarda en funcionar un trabajo?', 'Cada trabajo tiene su propio tiempo de manifestación. Puede funcionar en dos días, como también en un mes o más. Todo depende de la energía con la que se esté trabajando y, si es para alguien más, de su carácter y disposición hacia ti. La magia es poderosa, pero no es un botón de control: la paciencia y la fe son clave para ver los mejores resultados.', array['cuanto tarda', 'tiempo', 'demora', 'cuando funciona', 'rapido', 'dias']::text[], array['general']::text[], 'mistica', '[]'::jsonb, 3) on conflict (clave) do nothing;
insert into public.preguntas (clave, pregunta, respuesta, palabras_clave, aplica_a, emocion, acciones, orden) values ('otro-brujo', '¿Puedo hacer trabajos con otro brujo al mismo tiempo?', 'No mezcles energías con otro brujo ni intentes hacerte varios trabajos a la vez, porque las fuerzas chocan y pueden bloquear los resultados. Tampoco esperes que yo solucione de un día para otro lo que otro no pudo: la magia requiere paciencia y constancia.', array['otro brujo', 'otra bruja', 'varios trabajos', 'mezclar', 'otro trabajo']::text[], array['general']::text[], 'sorprendida', '[]'::jsonb, 4) on conflict (clave) do nothing;
insert into public.preguntas (clave, pregunta, respuesta, palabras_clave, aplica_a, emocion, acciones, orden) values ('energia-50-50', '¿De qué depende que el ritual funcione?', 'El éxito de cualquier ritual depende en un 50 % de mi energía y en un 50 % de la tuya. Si buscas resultados inmediatos o actúas desde la ansiedad, la desesperación o la indecisión, el trabajo puede debilitarse o incluso no funcionar.', array['depende', 'ansiedad', 'dudas', 'funcione', 'energia']::text[], array['general']::text[], 'mistica', '[]'::jsonb, 5) on conflict (clave) do nothing;
insert into public.preguntas (clave, pregunta, respuesta, palabras_clave, aplica_a, emocion, acciones, orden) values ('sencillo-supremo', '¿Qué diferencia hay entre un ritual sencillo y uno supremo?', 'Los rituales sencillos son trabajos energéticos progresivos que generan resultados de forma natural. Si buscas un trabajo más fuerte o potenciado, están los rituales supremos, que combinan varios trabajos en uno.', array['sencillo', 'supremo', 'diferencia', 'potenciado', 'mas fuerte']::text[], array['general']::text[], 'hablando', '[]'::jsonb, 6) on conflict (clave) do nothing;
insert into public.preguntas (clave, pregunta, respuesta, palabras_clave, aplica_a, emocion, acciones, orden) values ('lectura-previa', '¿Necesito una lectura antes de un trabajo de amor?', 'Sí. Todo trabajo de amor requiere previa lectura para conocer y comprender a profundidad los sentimientos de la persona y la situación en la que se encuentran.', array['lectura previa', 'lectura antes', 'tarot antes', 'necesito lectura']::text[], array['general', 'seccion:amor', 'seccion:supremo', 'seccion:amarres', 'seccion:tarot']::text[], 'mistica', '[{"tipo":"catalogo","etiqueta":"Ver tarot","seccion":"tarot"}]'::jsonb, 7) on conflict (clave) do nothing;
insert into public.preguntas (clave, pregunta, respuesta, palabras_clave, aplica_a, emocion, acciones, orden) values ('progresivo', '¿Los trabajos de amor cambian a la persona de inmediato?', 'Los trabajos avanzan de manera progresiva según el carácter y la disposición de la persona.', array['inmediato', 'de inmediato', 'cambia', 'progresivo']::text[], array['seccion:amor', 'seccion:supremo', 'seccion:amarres']::text[], 'mistica', '[]'::jsonb, 8) on conflict (clave) do nothing;
insert into public.preguntas (clave, pregunta, respuesta, palabras_clave, aplica_a, emocion, acciones, orden) values ('vela-refuerzo', '¿Para qué sirve la vela de refuerzo?', 'Tiene como propósito potenciar el trabajo, ya sea para acelerar sus efectos o, si ya surtió efecto, revitalizar su energía, porque con el tiempo puede perder intensidad. No es necesario repetir el mismo ritual sin antes hacer un refuerzo con la vela, y si el trabajo está tardando, puedes reforzarlo tantas veces como consideres necesario.', array['vela', 'refuerzo', 'velita', 'acelerar', 'potenciar']::text[], array['general', 'seccion:velas']::text[], 'mistica', '[{"tipo":"catalogo","etiqueta":"Ver velas","seccion":"velas"}]'::jsonb, 9) on conflict (clave) do nothing;
insert into public.preguntas (clave, pregunta, respuesta, palabras_clave, aplica_a, emocion, acciones, orden) values ('personalizado-precio', '¿Cuánto cuesta un ritual personalizado?', 'El precio final depende de la dificultad, los materiales y la carga energética del caso. Puedes consultarme sin compromiso y te doy una valoración honesta y detallada.', array['personalizado', 'a medida', 'precio personalizado', 'caso especial']::text[], array['general', 'seccion:personalizado']::text[], 'guino', '[{"tipo":"catalogo","etiqueta":"Ver rituales personalizados","seccion":"personalizado"}]'::jsonb, 10) on conflict (clave) do nothing;
insert into public.preguntas (clave, pregunta, respuesta, palabras_clave, aplica_a, emocion, acciones, orden) values ('moneda', '¿En qué moneda están los precios?', 'Los precios están en dólares (USD) y en pesos colombianos (COP).', array['moneda', 'dolares', 'pesos', 'usd', 'cop', 'precio']::text[], array['general']::text[], 'hablando', '[]'::jsonb, 11) on conflict (clave) do nothing;
insert into public.preguntas (clave, pregunta, respuesta, palabras_clave, aplica_a, emocion, acciones, orden) values ('estafas', 'Alguien me escribió diciendo ser Circe, ¿es real?', '¡Cuidado! Yo nunca escribo primero y solo atiendo desde mi WhatsApp oficial. Si alguien te contactó usando mi nombre, repórtalo.', array['estafa', 'falso', 'fraude', 'me escribio', 'me contacto', 'perfil falso', 'suplantar']::text[], array['general']::text[], 'sorprendida', '[{"tipo":"whatsapp","etiqueta":"Reportar perfil falso","mensaje":"Hola Circe, quiero reportar un perfil falso que usa tu nombre."}]'::jsonb, 12) on conflict (clave) do nothing;
insert into public.preguntas (clave, pregunta, respuesta, palabras_clave, aplica_a, emocion, acciones, orden) values ('obsesion-contacto', '¿Funciona si ya no tenemos contacto?', 'Este trabajo es recomendable cuando aún existe comunicación y contacto, ya que esto facilita que los efectos se manifiesten más rápido.', array['contacto', 'no hablamos', 'comunicacion', 'bloqueado']::text[], array['servicio:obsesion']::text[], 'hablando', '[]'::jsonb, 13) on conflict (clave) do nothing;
insert into public.preguntas (clave, pregunta, respuesta, palabras_clave, aplica_a, emocion, acciones, orden) values ('retorno-sentimientos', '¿El retorno cambia lo que siente por mí?', 'No. Este ritual únicamente facilita su regreso, sin alterar sus sentimientos o intenciones hacia ti. Si siente rabia, rencor o emociones negativas, regresará con esos mismos sentimientos; para que el retorno sea armonioso, lo ideal es combinarlo con otro ritual según tu caso.', array['sentimientos', 'rencor', 'rabia', 'armonioso', 'combinar']::text[], array['servicio:retorno']::text[], 'hablando', '[]'::jsonb, 14) on conflict (clave) do nothing;
insert into public.preguntas (clave, pregunta, respuesta, palabras_clave, aplica_a, emocion, acciones, orden) values ('vendaje-sentimientos', '¿El vendaje de amor hace que me quiera más?', 'Ayuda con su fidelidad y exclusividad en la relación, pero no cambia los sentimientos existentes de la persona.', array['fidelidad', 'querer', 'sentimientos', 'infiel']::text[], array['servicio:vendaje-de-amor']::text[], 'hablando', '[]'::jsonb, 15) on conflict (clave) do nothing;
insert into public.preguntas (clave, pregunta, respuesta, palabras_clave, aplica_a, emocion, acciones, orden) values ('amarre-corazon-juntos', '¿Se puede hacer si no estamos juntos?', 'Este amarre solo se realiza en parejas que están juntas.', array['juntos', 'separados', 'no estamos', 'pareja actual']::text[], array['servicio:amarre-de-corazon-con-las-siete-potencias-africanas']::text[], 'hablando', '[]'::jsonb, 16) on conflict (clave) do nothing;
insert into public.preguntas (clave, pregunta, respuesta, palabras_clave, aplica_a, emocion, acciones, orden) values ('sello-peticiones', '¿Cuántas peticiones puedo agregar?', 'Puedes agregar hasta cinco peticiones personalizadas, enfocadas únicamente en tu relación.', array['peticiones', 'pedir', 'cuantas']::text[], array['servicio:sello-de-amor-con-retorno']::text[], 'guino', '[]'::jsonb, 17) on conflict (clave) do nothing;
insert into public.preguntas (clave, pregunta, respuesta, palabras_clave, aplica_a, emocion, acciones, orden) values ('abre-camino-amor-peticiones', '¿Cuántas peticiones puedo hacer?', 'Tienes la oportunidad de pedir hasta 10 peticiones específicas, incluyendo cualidades emocionales y de carácter, y también rasgos físicos si así lo deseas.', array['peticiones', 'pedir', 'cuantas', 'rasgos']::text[], array['servicio:abre-camino-de-amor-supremo']::text[], 'guino', '[]'::jsonb, 18) on conflict (clave) do nothing;
insert into public.preguntas (clave, pregunta, respuesta, palabras_clave, aplica_a, emocion, acciones, orden) values ('novena-dias', '¿Cuánto dura la novena?', 'Se trabaja durante nueve días consecutivos.', array['novena', 'dias', 'cuanto dura']::text[], array['servicio:novena-personalizada', 'servicio:novena-personalizada-de-la-prosperidad']::text[], 'mistica', '[]'::jsonb, 19) on conflict (clave) do nothing;
insert into public.preguntas (clave, pregunta, respuesta, palabras_clave, aplica_a, emocion, acciones, orden) values ('separacion-suprema-dias', '¿Cuántos días dura la velación?', 'La velación se realiza durante siete días seguidos.', array['dias', 'velacion', 'cuanto dura']::text[], array['servicio:separacion-suprema']::text[], 'mistica', '[]'::jsonb, 20) on conflict (clave) do nothing;
insert into public.preguntas (clave, pregunta, respuesta, palabras_clave, aplica_a, emocion, acciones, orden) values ('laboral-accion', '¿Tengo que hacer algo yo para conseguir trabajo?', 'Sí. La magia abre puertas, pero tú debes cruzarlas. Es fundamental que también tomes acción: busca, postula y muévete. La energía se alineará a tu favor, pero el esfuerzo es clave para que la oportunidad llegue y se materialice.', array['hacer algo', 'postular', 'accion', 'esfuerzo']::text[], array['servicio:abre-camino-laboral']::text[], 'guino', '[]'::jsonb, 21) on conflict (clave) do nothing;
insert into public.preguntas (clave, pregunta, respuesta, palabras_clave, aplica_a, emocion, acciones, orden) values ('suerte-garantia', '¿Me garantiza que voy a ganar?', 'No garantiza ganancias fijas, pero sí maximiza tus posibilidades de éxito, abriendo caminos para que la suerte te favorezca en el momento justo.', array['ganar', 'garantiza', 'loteria', 'apuesta']::text[], array['servicio:suerte-rapida']::text[], 'guino', '[]'::jsonb, 22) on conflict (clave) do nothing;
insert into public.preguntas (clave, pregunta, respuesta, palabras_clave, aplica_a, emocion, acciones, orden) values ('salud-medico', '¿Reemplaza al médico o al tratamiento?', 'No. Es un apoyo espiritual: no sustituye atención médica ni terapias, pero trabaja a nivel energético para aportar fuerza, equilibrio y bienestar.', array['medico', 'tratamiento', 'terapia', 'reemplaza']::text[], array['servicio:refuerzo-para-tu-salud', 'servicio:ritual-de-limpieza-mental']::text[], 'hablando', '[]'::jsonb, 23) on conflict (clave) do nothing;
insert into public.preguntas (clave, pregunta, respuesta, palabras_clave, aplica_a, emocion, acciones, orden) values ('amuletos-como', '¿Cómo se hace la consagración?', 'Lo realizamos por videollamada, con los elementos que te indicaré.', array['como se hace', 'videollamada', 'elementos']::text[], array['servicio:consagracion-de-amuletos']::text[], 'feliz', '[]'::jsonb, 24) on conflict (clave) do nothing;
insert into public.preguntas (clave, pregunta, respuesta, palabras_clave, aplica_a, emocion, acciones, orden) values ('pocima-envio', '¿Hacen envíos de la pócima?', 'Si estás en Colombia y así lo deseas, puedo hacerte el envío físico del frasco. Si te encuentras en otro país, lo entierro en una maceta especial, activando su poder de igual manera para que continúe cumpliendo su función sin perder efectividad.', array['envio', 'enviar', 'domicilio', 'frasco', 'colombia']::text[], array['general', 'servicio:pocima-perfecta']::text[], 'feliz', '[]'::jsonb, 25) on conflict (clave) do nothing;
insert into public.preguntas (clave, pregunta, respuesta, palabras_clave, aplica_a, emocion, acciones, orden) values ('vela-abundancia-intencion', '¿Tengo que decirte mi intención?', 'Sí. Escríbeme tu intención para que la vela sea programada especialmente con tu energía.', array['intencion', 'programar', 'decir']::text[], array['servicio:vela-potencializadora-suprema-abundancia']::text[], 'mistica', '[]'::jsonb, 26) on conflict (clave) do nothing;
